import { cacheTag } from 'next/cache'

export type Post = {
  id: number
  title: string
  content: string
}

// In-memory store standing in for a real database.
const posts: Post[] = []
let nextId = 1

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return [...posts]
}

export async function insertPost(data: Omit<Post, 'id'>): Promise<Post> {
  const post = { id: nextId++, ...data }
  posts.push(post)
  return post
}

